TLM.f("Sancti/09-21",{"officium":"S. Matthæi Apostoli et Evangelistæ","rule":["ex C1a;","Gloria","Credo","Prefatio=Apostolis"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1a","sections":{"Introitus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Beáti Apóstoli et Evangelístæ Matthǽi, Dómine, précibus adjuvémur: ut, quod possibílitas nostra non óbtinet, ejus nobis intercessióne donétur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Ezechiélis Prophétæ"},{"k":"ref","la":"Ezech 1:10-14"},{"k":"text","la":"Similitúdo vultus quátuor animálium: fácies hóminis, et fácies leónis a dextris ipsórum quatuor: fácies autem bovis a sinístris ipsórum quátuor, et fácies áquilæ désuper ipsórum quátuor. Fácies eórum et pennæ eórum exténtæ désuper: duæ pennæ singulórum jungebántur et duæ tegébant córpora eórum: et unumquódque eórum coram fácie sua ambulábat: ubi erat ímpetus spíritus, illuc gradiebántur, nec revertebántur cum ambulárent. Et similitúdo animálium, aspéctus eórum quasi carbónum ignis ardéntium et quasi aspéctus lampadárum. Hæc erat visio discúrrens in médio animálium, splendor ignis, et de igne fulgur egrédiens. Et animália ibant et revertebántur in similitúdinem fúlguris coruscántis."}],"Graduale":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Te gloriosus Apostolórum chorus laudat, Dómine. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 9:9-13"},{"k":"text","la":"In illo témpore: Vidit Jesus hóminem sedéntem in telónio, Matthǽum nómine. Et"},{"k":"text","la":"ait illi: Séquere me. Et surgens, secútus est eum. Et factum est, discumbénte"},{"k":"text","la":"eo in domo, ecce, multi publicáni et peccatóres veniéntes discumbébant cum Jesu"},{"k":"text","la":"et discípulis ejus. Et vidéntes pharisæi, dicébant discípulis ejus: Quare cum"},{"k":"text","la":"publicánis et peccatóribus mandúcat Magíster vester? At Jesus áudiens, ait: Non est opus valéntibus médicus, sed male habéntibus. Eúntes autem díscite, quid est: Misericórdiam volo, et non sacrifícium. Non enim veni vocáre justos, sed peccatóres."}],"Offertorium":[{"k":"ref","la":"Ps 20:4-5"},{"k":"text","la":"Posuísti, Dómine, in cápite ejus corónam de lápide pretióso: vitam pétiit a te, et tribuísti ei, allelúja."}],"Secreta":[{"k":"text","la":"Supplicatiónibus beáti Matthæi Apóstoli et Evangelístæ, quǽsumus, Dómine, Ecclésiæ tuæ commendétur oblátio: cujus magníficis prædicatiónibus erúditur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 20:6"},{"k":"text","la":"Magna est glória ejus in salutári tuo: glóriam et magnum deI córem ímpones super eum, Dómine."}],"Postcommunio":[{"k":"text","la":"Percéptis, Dómine, sacraméntis, beáto Matthæo Apóstolo tuo et Evangelísta interveniénte, deprecámur: ut, quæ pro ejus celebráta sunt glória, nobis profíciant ad medélam."},{"k":"macro","name":"Per Dominum"}]},"hr":{"52236fd7918c9b03":{"t":"Ps 36, 30-31, Ps 36, 1\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu. (Ps 36, 1) Ne zaviđaj sreći grešnika i ne žesti se radi zlotvora.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu.","kn":"(Ps. 36, 30, 31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne će posrnuti. (Aleluja, Aleluja.) (Ps. 36, 1). Ne zaviđaj sreći ^rješnika i zlotvora! Slava Ocu. Pravednikova.","knRef":"Kniewald 1942, str. 814–815 (snimka 408) (OCR)"},"ec1f64e09f09b319":{"t":"<i>Pomolimo se</i>.\nPomogle nam, Gospodine, molitve blaženog apostola i evanđeliste Mateja, da po njegovu zagovoru postignemo, što ne možemo sami po sebi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomogle nas, Gospodine, molitve blaženoga apostola i evanđeliste ■ Mateja, da po njegovu zagovoru zadobijemo, što mogućnost naša ne zadobiva. Po G. n.","knRef":"Kniewald 1942, str. 714–715 (snimka 358) (OCR)"},"ac1109889c68227f":{"t":"Ez 1, 10-14\nČitanje proroka Ezekiela. Evo prilike lica četiriju životinja: lice čovjeka i lice lava s desne strane u sve četiri, lice vola s desne strane u sve četiri, i lice orla odozgo u sve četiri. Njihova lica kao i njihova krila bila su upravljena prema gore. Po dva njihova krila združila su se, a dva su im pokrivala tijelo i svaka je životinja stupala ravno. Išle su kamo ih je vodio duh, i nisu se vraćale dok su polazile. I lica su životinja slična usijanoj žeravi i gorućoj zublji. Vidjelo se, da među životinjama prolazi sjaj ognja, a iz ognja sijeva munja. I životinje su išle i vraćale se kao kad sijeva munja.","kn":"Čitanje proroka Ezekijela (1, 10-14). Prilika lica četiriju životinja: lice čovjeka i lice lava s desne strane ovih četiriju, lice vola s lijeve strane ovih četiriju, i lice orla odozgo ovih četiriju. Njihova lica kao i njihova krila bila su upravljena na gore. Po dva njihova krila združila su se^ a dva su .im pokrivala tijelo i svaka je od njih stupala . ravno^ Išle su, kamo ih je vodio duh. i nijesu se vraćale, dok su polazile. I lica su životinja slična usijanoj žeravici i gorućoj svijeći. Vidjelo se, da među životinjama prolazi sjaj ognja, a iz ognja sijeva munja. I životinje su išle naprijed i natrag kao kad sijeva munja.","knRef":"Kniewald 1942, str. 550–551 (snimka 276) (OCR)"},"3a4d180ecc7bd650":{"t":"Ps 111, 1-2\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. Silno će biti na zemlji njegovo potomstvo, rod će pravednika biti blagoslovljen.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nTebe, Gospodine, hvali slavni apostola zbor. <i>Aleluja</i>.","kn":"(Ps. 111, 1). Blago čovjeku, koji se boji .Boga, zapovijedi njegove žudi veoma. Silno će biti na zemlji potomstvo njegovo, blagoslovit ce se rod pravih.\n\nAleluja, aleiuja. Tebe Gospodine, hvali slavni apostolski zbor, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 714–715 (snimka 358) (OCR)"},"3c7d0fb0c4398079":{"t":"Mt 9, 9-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme ugleda Isus čovjeka koji se zvao Matej gdje sjedi kod carine i reče mu: Pođi za mnom! On ustade i pođe za njim. I kad je sjedio za stolom u njegovoj kući, došli su mnogi carinici i grješnici i sjedoše za stolom s Isusom i s njegovim učenicima. Kad su to vidjeli farizeji, pitali su njegove učenike: Zašto vaš učitelj jede s carinicima i grješnicima? Kad je to čuo Isus, odgovori: Zdravima ne treba liječnika nego bolesnima. Idite dakle i razumijte što znači: Hoću milosrđe a ne žrtve! Jer nisam došao zvati pravednike, nego grješnike.","kn":"t Slijedi sv. evanđelje po Mateju (9, 9-13). U ono vrijeme ugleda Isus čovjeka, koji se zvao Matej, gdje sjedi kod carine i reče mu: Pođi za mnom. Sv. Ciprijan i Justioa 26, IX. On ustade i pođe za njim. I kad je sjedio za stolom u njegovoj kući, došli su mnogi carinici i grješnicima? Kad je to čuo Isus, odgovori: Zdravima učenicima. Kad su to vidjeli farizeji, pitali su nje-, gove učenike: Zašto vaš učitelj jede s carinicima i grješnicima? Kad je to čuo Isus, odgovori: Zdravima ne treba liječnika, nego bolesnima. Idite : dakle 1 razumijte što znači: Hoću milosrđe, a ne žrtve!* Jer ja nijesam došao zvati pravednike, nego grješnike.","knRef":"Kniewald 1942, str. 714–715 (snimka 358) (OCR)"},"aa07239af1227556":{"t":"Ps 20, 4-5\nPostavio si Gospodine, na njegovu glavu vijenac od dragog kamenja. Život je tražio od tebe i dao si mu, <i>aleluja</i>.","kn":"(Ps. 20). Položio si. Gospodine, na glavu njegovu -vijenaic od drago,ga kamenja; život je tražio Tebe i dao si mu. Aleluja.","knRef":"Kniewald 1942, str. 716–717 (snimka 359) (OCR)"},"b13f97e79e94bf1f":{"t":"Preporučile ti, molimo, Gospodine, molitve blaženoga apostola i evanđeliste Mateja prinos tvoje Crkve, koju poučava njegovo divno propovijedanje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Preporučile , Ti, molimo. Gospodine, molitve blaženoga apostola i evanđeliste Mateja, prinos Tvoje Crkve, koju poučaje njegovo divno propovijedanje, po Gospodinu ...","knRef":"Kniewald 1942, str. 716–717 (snimka 359) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno. Tebe, Gospodine, vječni Pastiru, smjerno moliti, da ne ostaviš svoga stada, nego’ da ga po blaženim svojim apostolima sveudiljnom zaštitom čuvaš, te Tvojim stadom upravljaju isti vođe, koje si Ti odredio da ga vode kao pastiri i namjesnici Tvoga djelovanja. I toga radi pjevamo pjesmu slave Tvoje s anđelima i s arkanđelima, s prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"32650c179dbe9b23":{"t":"Ps 20, 6\nVelika je njegova slava u tvojemu spasenju, slavom i velikom ljepotom ukrasio si ga, Gospodine.","kn":"(Ps. 20, 6). Velika je slava njegova u spasenju Tvojsmu; slavu i veliku krasotu metnut ćeš na nj. Gospodine.","knRef":"Kniewald 1942, str. 716–717 (snimka 359) (OCR)"},"aee561cd507d892c":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, sveta otajstva, molimo po zagovoru tvoga blaženoga apostola i evanđeliste Mateja, da nam bude na spasenje, što smo proslavili njemu u čast.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, sveta otajstva, molimo zagovorom Tvoga svetog apostola i evanđeliste Mateja, da nam bude na spasenje,' što smo proslavili njemu u čast. Po G. n.","knRef":"Kniewald 1942, str. 716–717 (snimka 359) (OCR)"}}});
